def find_shapes(rows, cols, color, start_row, start_col, visited):
    """Find a shape of given color"""
    if start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols:
        return []
    if (start_row, start_col) in visited:
        return []
    if grid[start_row][start_col] != color:
        return []

    shape = [(start_row, start_col)]
    visited.add((start_row, start_col))

    rows, cols = len(grid), len(grid[0])

    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = start_row + dr, start_col + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if (nr, nc) not in visited and grid[nr][nc] == color:
                shape.extend(find_shapes(rows, cols, color, nr, nc, visited.copy()))

    return shape

